{
    public class WinRateRule
    {
        public int TierMin;
        public int TierMax;
        public int NumGames;
        public float WinRate;
        public RuleComparisonType ComparisonType;
        public int TierChange;

        public WinRateRule(int tierMin, int tierMax, int numGames, float winRate, RuleComparisonType comparisonType, int tierChange)
        {
            TierMin = tierMin;
            TierMax = tierMax;
            NumGames = numGames;
            WinRate = winRate;
            ComparisonType = comparisonType;
            TierChange = tierChange;
        }

        public static WinRateRule[] Defaults = new WinRateRule[]
        {
            // If they win any game while in or below tier -2, they are promoted
            new WinRateRule(-5, -2, 1, 1.0f, RuleComparisonType.GreaterThanOrEqualTo, 1),

            // Win rate over 80% last 10 games you are promoted
            new WinRateRule(-1, 100, 10, 0.8f, RuleComparisonType.GreaterThanOrEqualTo, 1),

            // Win rate over 50% last 10 games, you are demoted
            new WinRateRule(-1, 100, 10, 0.5f, RuleComparisonType.LessThanOrEqualTo, -1),

            // Lost last 4 games, you are demoted
            new WinRateRule(-1, 100, 4, 0.0f, RuleComparisonType.LessThanOrEqualTo, -1),
        };

        public override string ToString()
        {
            return $"TierMin: {TierMin}, TierMax: {TierMax}, NumGames: {NumGames}, WinRate: {WinRate}, ComparisonType: {ComparisonType}, TierChange: {TierChange}";
        }
    }
